import{_ as e,o as t,c as n,a2 as s}from"./chunks/framework.CqGPl1zp.js";const i="/newx-doc/assets/%E8%85%BE%E8%AE%AF%E6%B7%B7%E5%85%83-%E5%AE%98%E6%96%B9.D1cWIIBl.png",u=JSON.parse('{"title":"【模型接入】腾讯混元","description":"","frontmatter":{},"headers":[],"relativePath":"ai/hunyuan.md","filePath":"ai/hunyuan.md","lastUpdated":null}'),r={name:"ai/hunyuan.md"};function h(l,a,o,d,p,c){return t(),n("div",null,[...a[0]||(a[0]=[s('<h1 id="【模型接入】腾讯混元" tabindex="-1">【模型接入】腾讯混元 <a class="header-anchor" href="#【模型接入】腾讯混元" aria-label="Permalink to &quot;【模型接入】腾讯混元&quot;">​</a></h1><p>项目基于 Spring AI + 自己实现的 <code>models/hunyuan</code>，实现 <a href="https://cloud.tencent.com/product/hunyuan" target="_blank" rel="noreferrer">hunyuan 混元大模型</a> 的接入：</p><table tabindex="0"><thead><tr><th>功能</th><th>模型</th><th>Spring AI 客户端</th></tr></thead><tbody><tr><td>AI 对话</td><td>hy3-preview 等</td><td>HunYuanChatModel</td></tr><tr><td>AI 绘画</td><td><a href="https://cloud.tencent.com/document/product/1729/105925" target="_blank" rel="noreferrer">混元生图</a> 等</td><td>暂未接入</td></tr></tbody></table><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>由于腾讯混元是非开源的模型，所以无法私有化部署，需要去官网申请 API Key，然后通过 Spring AI 提供的客户端接入。</p><h3 id="_1-1-申请腾讯密钥" tabindex="-1">1.1 申请腾讯密钥 <a class="header-anchor" href="#_1-1-申请腾讯密钥" aria-label="Permalink to &quot;1.1 申请腾讯密钥&quot;">​</a></h3><p>① 在 <a href="https://curl.qcloud.com/cxA9d2Ik" target="_blank" rel="noreferrer">腾讯云</a> 上，注册一个账号。</p><p>② 在 <a href="https://console.cloud.tencent.com/tokenhub" target="_blank" rel="noreferrer">TokenHub 控制台</a> 上开通混元模型，并在 <a href="https://console.cloud.tencent.com/tokenhub/apikey" target="_blank" rel="noreferrer">API Key 管理</a> 创建一个 API Key 密钥。</p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。只需要填写“密钥”，不需要填写“自定义 API URL”（项目默认使用 TokenHub 地址）。如下图所示：</p><p><img src="'+i+`" alt="官方的密钥配置"></p><h2 id="_2-模型配置" tabindex="-1">2. 模型配置 <a class="header-anchor" href="#_2-模型配置" aria-label="Permalink to &quot;2. 模型配置&quot;">​</a></h2><p>友情提示：</p><p>目前 <code>ai_model</code> 表中，已经预置了一些模型，可以直接使用！！！</p><h3 id="_2-1-ai-对话" tabindex="-1">2.1 AI 对话 <a class="header-anchor" href="#_2-1-ai-对话" aria-label="Permalink to &quot;2.1 AI 对话&quot;">​</a></h3><p>使用 <a href="./chat">《AI 对话》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的聊天模型。</p><p>模型可以在 <a href="https://console.cloud.tencent.com/tokenhub/models?regionId=1&amp;from=featured" target="_blank" rel="noreferrer">TokenHub 模型广场</a> 查看。</p><p>不同模型的 <code>max_tokens</code>（回复数 Token 数）上限不同，可以参考下表填写：</p><table tabindex="0"><thead><tr><th>模型标识</th><th><code>max_tokens</code> 最大输出 Tokens</th></tr></thead><tbody><tr><td><code>hy3-preview</code></td><td>131072</td></tr></tbody></table><h3 id="_2-2-ai-绘图" tabindex="-1">2.2 AI 绘图 <a class="header-anchor" href="#_2-2-ai-绘图" aria-label="Permalink to &quot;2.2 AI 绘图&quot;">​</a></h3><p>TODO 等待 HunYuan ImageModel 客户端！</p><h2 id="_3-如何使用" tabindex="-1">3. 如何使用？ <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 HunYuanChatModel 等对象，需要把 <code>application.yaml</code> 配置文件里的 <code>yudao.ai.hunyuan</code> 配置项，替换成你的！</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">yudao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    hunyuan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 腾讯混元</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${HUNYUAN_API_KEY}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hy3-preview</span></span></code></pre></div><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getChatModel(...)</code> 方法，获取对应的模型对象。</p><hr><p>① 和 ② 这两者的后续使用，就是标准的 Spring AI 客户端的使用，调用对应的方法即可。</p><p>另外，HunYuanChatModelTests 里有对应的测试用例，可以参考。</p>`,28)])])}const _=e(r,[["render",h]]);export{u as __pageData,_ as default};
